/* mailBrand.js — the white-on-dark Salam logo embedded as a CID attachment in every mail the console sends.
 * Same asset as the Undertaking Consent System (public/brand/salam-logo-dark.png, 54192 bytes); embedded so
 * deploy.sh (which ships server/src/*.js only) can never leave it behind. Hosted images are blocked by most mail
 * clients until the reader clicks "load images" — a CID attachment renders immediately, everywhere. */
'use strict';
const CID = 'salam-logo@operations-console';
const PNG_B64 = '';
const buffer = () => Buffer.from(PNG_B64, 'base64');
const attachment = () => ({ filename: 'salam-logo.png', content: buffer(), contentType: 'image/png', cid: CID });
module.exports = { CID, attachment, buffer };
